pageCss:
.sp-scroll{overflow-x:auto;margin:10px 0 12px}
.sp-table{border-collapse:collapse;font-size:var(--text-micro);width:100%;min-width:520px;background:var(--surface-window)}
.sp-table th{text-align:left;background:var(--surface-desktop);border:1px solid var(--slate-84);padding:4px 7px;font-family:var(--font-caption);color:var(--slate-38)}
.sp-table td{border:1px solid var(--slate-90);padding:4px 7px;vertical-align:top;line-height:1.45}
.sp-table tbody tr:nth-child(odd) td{background:var(--paper-cool)}
.sp-n{text-align:right;font-family:var(--font-mono);white-space:nowrap}
.sp-note{font-size:var(--text-xs);color:var(--ink-soft)}
.sp-code{background:var(--row-alt);border:1px solid var(--slate-84);border-left:3px solid var(--luna-44);padding:8px 10px;margin:0 0 12px;overflow-x:auto;font-size:var(--text-xs);line-height:1.5}
.sp-code code{white-space:pre;font-family:var(--font-mono)}
.sp-demo{border:1px solid var(--slate-73);background:var(--row-alt);margin:14px 0 16px;box-shadow:var(--bevel-sunken)}
.sp-pad{position:relative;height:240px;display:grid;grid-template-columns:repeat(3,1fr);grid-template-rows:1fr 1fr;place-items:center;background:var(--surface-field);border-bottom:1px solid var(--slate-84);overflow:hidden;touch-action:manipulation}
.sp-link{font:inherit;font-size:var(--text-sm);padding:6px 14px;border:1px solid var(--slate-73);background:var(--grad-button);border-radius:var(--radius-control);color:var(--link);cursor:pointer;text-decoration:underline}
.sp-at0{justify-self:start;margin-left:12%}.sp-at2{align-self:end;margin-bottom:18%}.sp-at3{align-self:start;margin-top:14%}.sp-at5{justify-self:end;margin-right:12%}
.sp-link.sp-guessed{outline:2px dotted var(--luna-44);outline-offset:2px}
.sp-dot{position:absolute;left:-5px;top:-5px;width:10px;height:10px;border-radius:50%;background:var(--danger);opacity:.7;pointer-events:none}
.sp-out{padding:8px 10px;font-size:var(--text-xs)}
.sp-hint{margin:0;color:var(--ink-soft)}
.sp-row{display:grid;grid-template-columns:9.5em 1fr 4.5em;gap:8px;align-items:center;margin:3px 0}
.sp-bar{height:10px;background:var(--luna-44);min-width:1px}
.sp-bar.sp-html{background:var(--go)}
.sp-ms{text-align:right;font-family:var(--font-mono)}
@media (max-width:480px){.sp-pad{height:200px}.sp-row{grid-template-columns:7em 1fr 4em}}

pageJs:
(function () {
  // The demo times each strategy's trigger against the visitor's click and
  // fetches nothing. The predictor here is the same arithmetic the lab arm ran.
  var pad = document.getElementById("sp-pad"), dot = document.getElementById("sp-dot"), out = document.getElementById("sp-out");
  if (!pad || !dot || !out) return;
  var HISTORY = 8, AHEAD = 120, pts = [], raf = 0, guessed = {}, entered = {}, down = 0;
  var now = function () { return performance.now(); };
  function predict() {
    raf = 0;
    var a = pts[0], b = pts[pts.length - 1], dt = b[2] - a[2];
    var vx = dt > 0 ? (b[0] - a[0]) / dt : 0, vy = dt > 0 ? (b[1] - a[1]) / dt : 0;
    var box = pad.getBoundingClientRect();
    dot.hidden = false;
    dot.style.transform = "translate(" + (b[0] + vx * AHEAD - box.left) + "px," + (b[1] + vy * AHEAD - box.top) + "px)";
    var steps = [0, 1 / 3, 2 / 3, 1];
    for (var i = 0; i < steps.length; i++) {
      var el = document.elementFromPoint(b[0] + vx * AHEAD * steps[i], b[1] + vy * AHEAD * steps[i]);
      var link = el && el.closest("[data-sp]");
      if (link) {
        var k = link.getAttribute("data-sp");
        if (!(k in guessed)) { guessed[k] = now(); link.classList.add("sp-guessed"); }
        return;
      }
    }
  }
  pad.addEventListener("pointermove", function (e) {
    if (e.pointerType !== "mouse") return;
    pts.push([e.clientX, e.clientY, e.timeStamp]);
    if (pts.length > HISTORY) pts.shift();
    if (!raf) raf = requestAnimationFrame(predict);
  });
  pad.addEventListener("pointerleave", function () { dot.hidden = true; pts = []; });
  pad.addEventListener("pointerover", function (e) {
    var link = e.target.closest && e.target.closest("[data-sp]");
    if (link) entered[link.getAttribute("data-sp")] = now();
  });
  pad.addEventListener("pointerdown", function () { down = now(); });
  function el(tag, cls, text) {
    var node = document.createElement(tag);
    if (cls) node.className = cls;
    if (text != null) node.textContent = text;
    return node;
  }
  // Bars scale to the click's largest head start, so a long rest still shows
  // the gaps between strategies; the ms column carries the absolute numbers.
  function row(label, ms, scale, cls) {
    var bar = el("span", "sp-bar" + (cls || ""));
    bar.style.width = Math.max(0, Math.min(100, (ms / scale) * 100)) + "%";
    var r = el("div", "sp-row");
    r.append(el("span", "", label), bar, el("span", "sp-ms", Math.round(ms) + " ms"));
    return r;
  }
  pad.addEventListener("click", function (e) {
    var link = e.target.closest && e.target.closest("[data-sp]");
    if (!link) return;
    var k = link.getAttribute("data-sp"), click = now(), pd = down || click, enter = entered[k] == null ? pd : entered[k];
    var hovered = pd - enter;
    var moderate = hovered >= 200 ? enter + 200 : pd;
    var hover50 = hovered >= 50 ? enter + 50 : pd;
    var predictor = k in guessed ? Math.min(guessed[k], pd) : pd;
    var head = el("p", "sp-hint", "Head start before your click on ");
    head.append(el("code", "", k), ", after resting " + Math.round(Math.max(0, hovered)) + " ms on it:");
    var leads = [click - moderate, click - predictor, click - hover50, click - Math.min(predictor, hover50), click - hover50];
    var scale = Math.max.apply(null, leads.concat(1));
    out.replaceChildren(head,
      row("moderate (today)", leads[0], scale), row("predictor", leads[1], scale), row("50 ms hover", leads[2], scale),
      row("combo, HTML", leads[3], scale, " sp-html"), row("combo, render", leads[4], scale));
    guessed = {}; entered = {}; down = 0;
    var tagged = pad.querySelectorAll(".sp-guessed");
    for (var j = 0; j < tagged.length; j++) tagged[j].classList.remove("sp-guessed");
  });
})();
